<template>
  <div class="container">
    <div class="row">
      <h2>Periodic Transactions</h2>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
        <div class="block-data block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your <b><i>periodic transactions</i></b> that will automatically add transaction records in <b><i>finance</i></b> tab. This way you will no longer need to remember to input your subscription expenses!
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-8 col-md-9">
        <div class="block block-data inner">
          <div class="inner">
            <div class="searchbar">
              <button id="NewButton" @click="insert()" data-toggle="modal" data-target="#detailModal" class="btn btn-primary up"><b>+</b> Add Transaction</button>
              <input id="Search" class="form-control search-box financeForm" maxlength="100" placeholder="Search" v-model="$store.state.searchString" @keyup="keyup" />
              <multiselect class="pageSize" id="PageFilter" v-model="pageSize" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="['10','15','20','25']" :preselectFirst="true" :allowEmpty="false"
                placeholder="Select" openDirection="bottom" >
              </multiselect>
            </div>
            <div class="table-place">
              <table class="table periodic-transactions">
                <thead>
                    <th class="periodic-transactions-nr">
                        Nr.
                    </th>
                    <th class="periodic-transactions-name">
                        Name
                    </th>
                    <th class="periodic-transactions-next-run">
                        Schedule
                    </th>
                    <th class="periodic-transactions-is-active">
                        Is Active
                    </th>
                </thead>
                <tbody>
                  <tr v-if="$store.state.dataset.items.length == 0">
                    <td colspan="5" class="no-data">No data available in table</td>
                  </tr>
                  <tr v-else v-for="(row, i) in $store.state.dataset.items" :key="row.id" @click="edit(row, i)" data-toggle="modal" data-target="#detailModal" :class="selected == row.id ? 'selected' : ''">
                    <td class="periodic-transactions-nr">
                      {{i + 1 + $store.state.from}}
                    </td>
                    <td class="periodic-transactions-name">
                      <div class="overflow-ellipsis">{{row.name}}</div>
                    </td>
                    <td class="periodic-transactions-descriptions">
                      <div class="overflow-ellipsis">On {{getDayFromCronExpression(row.cronExpression)}} of {{getMonthFromCronExpression(row.cronExpression)}}</div>
                    </td>
                    <td class="periodic-transactions-active">
                      {{row.isActive ? "Yes" : "No"}}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
            <Pagination :visibleButtonNumber="5" :baseUrl="'/api/v1/periodicTransactions/List'" :mvvMGetter="getMvvMPeriodicTransaction()" />
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
        <div class="block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your <b><i>periodic transactions</i></b> that will automatically add transaction records in <b><i>finance</i></b> tab. This way you will no longer need to remember to input your subscription expenses!
          </div>
        </div>
      </div>
    </div>
  </div>

  <div id="detailModal" class="modal fade" role="dialog">
    <div class="vertical-alignment-helper">
      <div class="modal-dialog vertical-align-center">
        <div class="modal-content">
          <div class="modal-header">
            <button type="button" class="close" data-dismiss="modal">&times;</button>
            <h4 class="modal-title">
            </h4>
          </div>
          <div class="modal-body">
            <label for="Name">Name</label>
            <br />
            <input id="Name" class="form-control form-text-valid" maxlength="100" @change="change($event)" v-on:keyup.enter="focus()" v-model="name" />
            <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !name.trim()">*</span>
            <br />
            <br />
            <label for="Types">Type</label>
            <br />
            <multiselect class="form-text-valid" id="Types" v-model="selectedType" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="types" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                placeholder="Select" track-by="id" label="name" openDirection="bottom" >
              </multiselect>
            <br />
            <br />
            <div v-if="selectedType?.name == 'Transfer'">
              <label for="Accounts">Source account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedSourceAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="accounts" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
              <label for="Accounts">Destination account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="getAccounts()" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
            </div>
            <div v-else>
              <label for="Accounts">Account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="accounts" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
              <label for="Names">Category</label>
              <br />
              <multiselect class="form-text-valid" id="Names" v-model="selectedName" :show-labels="false"
                  :closeOnSelect="true" :options="names" group-values="categories" group-label="name" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="name" openDirection="bottom" >
                  <template #noResult>
                    <span>No categories found.</span>
                  </template>
                </multiselect>
              <br />
              <br />
            </div>
            <label for="Amount">Amount</label>
            <br />
            <input type="number" id="Amount" class="form-control form-text-valid" v-on:keyup.enter="focus()" @change="changeAmount()" v-model="amount" />
            <br />
            <br />
            <label for="CronExpression">Schedule</label>
            <br />
            <div class="cronExpression">
              <div class="cronExpressionRow">
                <div class="cronExpressionColumn">On</div>
                <div class="cronExpressionColumn">
                    <multiselect id="CronExpressionDays" v-model="day" :searchable="false" :show-labels="false"
                    :closeOnSelect="true" :options="days" :preselectFirst="true" :allowEmpty="false"
                    track-by="id" label="name" openDirection="bottom" >
                  </multiselect>
                </div>
              </div>
              <div class ="cronExpressionRow">
                <div class="cronExpressionColumn">of</div>
                <div class="cronExpressionColumn">
                  <multiselect id="CronExpressionMonths" v-model="month" :searchable="false" :show-labels="false"
                    :closeOnSelect="true" :options="months" :preselectFirst="true" :allowEmpty="false"
                    track-by="id" label="name" openDirection="bottom" >
                  </multiselect>
                </div>
              </div>
            </div>
            <br />
            <label for="StartDate">Start date</label>
            <br />
            <VueDatePicker id="StartDate" v-model="startDate" :enable-time-picker="false" :text-input="textInputOptions" v-on:keyup.enter="focus()" :clearable="false" :format="formatSingle" />
            <br />
            <label for="EndDate">End date</label>
            <br />
            <VueDatePicker id="EndDate" v-model="endDate" :min-date="getMinDate()" :enable-time-picker="false" :text-input="textInputOptions" v-on:keyup.enter="focus()" :clearable="true" :format="formatSingle" />
            <br />
            <div class="checkbox isActiveLabel">
              <div class="isActiveLabel"><b>Is Active</b></div>
              <input type="checkbox" id="IsActiveCheckBox" value=this.isActive @change="isActive = !isActive" />
              <label for="IsActiveCheckBox"></label>
            </div>
          </div>
          <div class="modal-footer">
            <div id="newControl">
              <button id="AddButton" @click="addRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <div id="editControl">
              <button id="DeleteButton" @click="deleteRecord($event)" class="btn btn-danger leftside">Delete</button>
              <button id="SaveButton" @click="saveRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <button id="close" type="button" class="btn btn-default rightside" data-dismiss="modal" style="display:inline-block">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import jQuery from "jquery";
import Pagination from '../../Pagination/Pagination.vue';
import CommunicationHelpers from '../../../helpers/CommunicationHelpers.js';
import { GetMvvMPeriodicTransaction } from "../../../models/MvvMPeriodicTransaction.js";
import Dataset from '@/models/Dataset';
import Multiselect from 'vue-multiselect';
import VueDatePicker from '@vuepic/vue-datepicker';
import '@vuepic/vue-datepicker/dist/main.css';
import { addDays } from 'date-fns';
const $ = jQuery;
window.$ = $;

export default {
  name: "PeriodicTransactions",
  components: {
    Pagination,
    Multiselect,
    VueDatePicker
  },
  data() {
    return {
      pageSize: 10,
      selected: null,
      selectedPeriodicTransaction: null,
      name: "",
      oldName: "",
      types: [],
      selectedType: null,
      names: [],
      accounts: [],
      selectedName: null,
      selectedAccount: null,
      selectedSourceAccount: null,
      amount: 0.01,
      cronExpression: "0 0 * * *",
      oldCronExpression: "0 0 * * *",
      startDate: new Date().toISOString().split('T')[0],
      endDate: null,
      isActive: false,
      triedSubmitting: false,
      textInputOptions: {
        format: 'yyyy-MM-dd'
      },
      month: null,
      months: [
        { id: '*', name: 'every month' },
        { id: 1, name: 'January' },
        { id: 2, name: 'February' },
        { id: 3, name: 'March' },
        { id: 4, name: 'April' },
        { id: 5, name: 'May' },
        { id: 6, name: 'June' },
        { id: 7, name: 'July' },
        { id: 8, name: 'August' },
        { id: 9, name: 'September' },
        { id: 10, name: 'October' },
        { id: 11, name: 'November' },
        { id: 12, name: 'December' }
      ],
      day: null,
      days: [
        { id: '*', name: 'every day' },
        { id: 1, name: '1st' },
        { id: 2, name: '2nd' },
        { id: 3, name: '3rd' },
        { id: 4, name: '4th' },
        { id: 5, name: '5th' },
        { id: 6, name: '6th' },
        { id: 7, name: '7th' },
        { id: 8, name: '8th' },
        { id: 9, name: '9th' },
        { id: 10, name: '10th' },
        { id: 11, name: '11th' },
        { id: 12, name: '12th' },
        { id: 13, name: '13th' },
        { id: 14, name: '14th' },
        { id: 15, name: '15th' },
        { id: 16, name: '16th' },
        { id: 17, name: '17th' },
        { id: 18, name: '18th' },
        { id: 19, name: '19th' },
        { id: 20, name: '20th' },
        { id: 21, name: '21st' },
        { id: 22, name: '22nd' },
        { id: 23, name: '23rd' },
        { id: 24, name: '24th' },
        { id: 25, name: '25th' },
        { id: 26, name: '26th' },
        { id: 27, name: '27th' },
        { id: 28, name: '28th' },
        { id: 29, name: '29th' },
        { id: 30, name: '30th' },
        { id: 31, name: '31st' }
      ]
    }
  },
  beforeMount() {
    this.$store.state.dataset = new Dataset();
  },
  async mounted() {
    this.$store.state.loading = true;

    await this.setup();

    this.$store.state.loading = false;
  },
  methods: {
    focus() {
      if(this.selected) {
        document.getElementById("SaveButton").click();
      } else {
        document.getElementById("AddButton").click();
      }
    },
    async setup() {
      this.types = await CommunicationHelpers.apiDataCall("/api/v1/periodicTransactions/ListTypes", this.$store.state, 'GET', null, false);
      this.names = await CommunicationHelpers.apiDataCall("/api/v1/periodicTransactions/ListCategories", this.$store.state, 'GET', null, false);
      this.accounts = await CommunicationHelpers.apiDataCall("/api/v1/periodicTransactions/ListAccounts", this.$store.state, 'GET', null, false);

      if(this.names.length == 0) {
        this.$router.push('Categories');
      } else {
        this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
        this.selectedAccount = this.getDefaultAccount(true);
        this.selectedSourceAccount = this.getDefaultAccount(false);
        this.selectedType = this.types[0];
      }

      this.$store.state.dataset.setPerPage(this.pageSize);
      await this.search();
    },
    async search() {
      this.$store.state.dataset.currentPage = 1;
      this.selected = null;
      this.selectedPeriodicTransaction= null;

      await this.getData();
    },
    async keyup() {
      // if (this.$store.state.loading) {
      //   event.preventDefault();
      // } else {
        await this.search();
      // }
    },
    formatSingle(date) {
      return date.toISOString().split('T')[0];
    },
    customNameLabel({name, parentId, id}) {
      let toReturn = name;
      let found = this.names.find(item => item.id == parentId);

      if (found && id != found.id) {
        toReturn = found.name + " › " + toReturn;
      }

      return toReturn;
    },
    insert() {
      this.selected = "";
      this.selectedPeriodicTransaction = null;
      this.oldName = "";
      this.name = "";
      this.oldCronExpression = "0 0 * * *";
      this.cronExpression = "0 0 * * *";

      document.getElementsByClassName("modal-title")[0].innerHTML = "Add new record";
      document.getElementById("newControl").style.display = "block";
      document.getElementById("editControl").style.display = "none";
    },
    edit(row, i) {
      this.selected = row.id;
      this.selectedPeriodicTransaction = this.getSelectedPeriodicTransaction();

      let isActive = document.getElementById("IsActiveCheckBox");
      if (row.isActive && isActive) {
        isActive.setAttribute("checked", "checked");
      }

      let searchByNameId = row.transaction.category?.id;

      if (row.transaction.category && row.transaction.category.categories && row.transaction.category.categories.length > 0) {
        searchByNameId = row.transaction.category.categories[0].id;
      }

      let foundNames = null;
      this.names.forEach(name => {
        if (name.id == searchByNameId) {
          foundNames = name;
        } else {
          var subcategory = name.categories.find(item => item.id == searchByNameId);
          if (subcategory) {
            foundNames = subcategory;
          }
        }
      });

      foundNames = foundNames ?? this.names[0]?.categories[0] ?? this.names[0];

      let foundAccount = null;
      this.accounts.forEach(account => {
        if (account.id == row.transaction.account?.id) {
          foundAccount = account;
        }
      });

      let foundSourceAccount = null;
      this.accounts.forEach(account => {
        if (account.id == row.transaction.sourceAccount?.id) {
          foundSourceAccount = account;
        }
      });

      this.name = row.name.trim();
      this.selectedName = foundNames;
      this.selectedAccount = foundAccount;
      this.selectedSourceAccount = foundSourceAccount;
      this.selectedType = row.transaction.type;
      this.amount = row.transaction.amount;
      this.startDate = row.startDate.split('T')[0];
      this.endDate = row.endDate ? row.endDate.split('T')[0] : null;
      this.cronExpression = row.cronExpression.trim();
      this.isActive = row.isActive;

      this.oldName = row.name.trim();
      this.oldNames = foundNames;
      this.oldAccount = foundAccount;
      this.oldSourceAccount = foundSourceAccount;
      this.oldType = row.transaction.type;
      this.oldAmount = row.transaction.amount;
      this.oldStartDate = row.startDate.split('T')[0];
      this.oldEndDate = row.endDate ? row.endDate.split('T')[0] : null;
      this.oldCronExpression = row.cronExpression.trim();
      this.oldIsActive = row.isActive;

      document.getElementsByClassName("modal-title")[0].innerHTML = "Edit record nr. <b>" + (i + 1 + this.$store.state.from) + "</b>";
      document.getElementById("newControl").style.display = "none";
      document.getElementById("editControl").style.display = "block";
    },
    getSelectedPeriodicTransaction() {
      return this.$store.state.dataset.items.find(periodicTransaction => periodicTransaction.id == this.selected);
    },
    async addRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim() || !this.cronExpression.trim()) {
        event.preventDefault();
      } else {
        this.$store.state.loading = true;

        this.triedSubmitting = false;

        this.changeDate();
        this.$store.state.periodicTransactions.id = 0;
        this.$store.state.periodicTransactions.name = this.name.trim();
        this.$store.state.periodicTransactions.cronExpression = this.cronExpression.trim();
        this.$store.state.periodicTransactions.startDate = this.startDate;
        this.$store.state.periodicTransactions.endDate = this.endDate;
        this.$store.state.periodicTransactions.isActive = this.isActive;
        this.$store.state.periodicTransactions.transaction.category = this.selectedName;
        this.$store.state.periodicTransactions.transaction.account = this.selectedAccount;
        this.$store.state.periodicTransactions.transaction.sourceAccount = this.selectedSourceAccount;
        this.$store.state.periodicTransactions.transaction.type = this.selectedType;
        this.$store.state.periodicTransactions.transaction.amount = this.amount;

        let request = {
          id: this.$store.state.periodicTransactions.id,
          name: this.$store.state.periodicTransactions.name,
          cronExpression: this.$store.state.periodicTransactions.cronExpression,
          startDate: this.$store.state.periodicTransactions.startDate,
          endDate: this.$store.state.periodicTransactions.endDate,
          isActive: this.$store.state.periodicTransactions.isActive,
          transaction: {
            category: this.$store.state.periodicTransactions.transaction.category,
            account: this.$store.state.periodicTransactions.transaction.account,
            sourceAccount: this.$store.state.periodicTransactions.transaction.sourceAccount,
            type: this.$store.state.periodicTransactions.transaction.type,
            amount: this.$store.state.periodicTransactions.transaction.amount
          }
        };

        if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/periodictransactions", this.$store.state, 'POST', request, true))) {
          this.name = "";
          this.cronExpression = "0 0 * * *";
          this.isActive = false;
          this.startDate = new Date().toISOString().split('T')[0];
          this.endDate = null;
          this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
          this.selectedAccount = this.getDefaultAccount(true);
          this.selectedSourceAccount = this.getDefaultAccount(false);
          this.selectedType = this.types[0];
          this.amount = 0.01;

          document.getElementById("close").click();
          await this.search();
        }

        this.$store.state.loading = false;
      }
    },
    async saveRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim() && !this.cronExpression.trim()) {
        event.preventDefault();
      } else {
        this.triedSubmitting = false;

        this.changeDate();

        if((this.name.trim() != this.oldName ||
            this.selectedName != this.oldNames ||
            this.selectedAccount != this.oldAccount ||
            this.selectedSourceAccount != this.oldSourceAccount ||
            this.selectedType != this.oldType ||
            this.amount != this.oldAmount ||
            this.startDate != this.oldStartDate ||
            this.endDate != this.oldEndDate ||
            this.cronExpression.trim() != this.oldCronExpression ||
            this.isActive != this.oldIsActive) && this.selected) {
          this.$store.state.loading = true;

          this.$store.state.periodicTransactions.id = this.selected;

          this.$store.state.periodicTransactions.name = this.name.trim();
          this.$store.state.periodicTransactions.cronExpression = this.cronExpression.trim();
          this.$store.state.periodicTransactions.startDate = this.startDate;
          this.$store.state.periodicTransactions.endDate = this.endDate;
          this.$store.state.periodicTransactions.isActive = this.isActive;
          this.$store.state.periodicTransactions.transaction.category = this.selectedName;
          this.$store.state.periodicTransactions.transaction.account = this.selectedAccount;
          this.$store.state.periodicTransactions.transaction.sourceAccount = this.selectedSourceAccount;
          this.$store.state.periodicTransactions.transaction.type = this.selectedType;
          this.$store.state.periodicTransactions.transaction.amount = this.amount;

          let request = {
            id: this.$store.state.periodicTransactions.id,
            name: this.$store.state.periodicTransactions.name,
            cronExpression: this.$store.state.periodicTransactions.cronExpression,
            startDate: this.$store.state.periodicTransactions.startDate,
            endDate: this.$store.state.periodicTransactions.endDate,
            isActive: this.$store.state.periodicTransactions.isActive,
            transaction: {
              category: this.$store.state.periodicTransactions.transaction.category,
              account: this.$store.state.periodicTransactions.transaction.account,
              sourceAccount: this.$store.state.periodicTransactions.transaction.sourceAccount,
              type: this.$store.state.periodicTransactions.transaction.type,
              amount: this.$store.state.periodicTransactions.transaction.amount
            }
          };

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/periodictransactions", this.$store.state, 'PUT', request, true))) {
            this.name = "";
            this.cronExpression = "0 0 * * *";
            this.isActive = false;
            this.startDate = new Date().toISOString().split('T')[0];
            this.endDate = null;
            this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
            this.selectedAccount = this.getDefaultAccount(true);
            this.selectedSourceAccount = this.getDefaultAccount(false);
            this.selectedType = this.types[0];
            this.amount = 0.01;
            
            document.getElementById("close").click();

            await this.search();
          }

          this.$store.state.loading = false;
        } else {
          document.getElementById("close").click();
        }
      }
    },
    async deleteRecord(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to delete?")) {
          this.$store.state.loading = true;

          this.$store.state.periodicTransactions.id = this.selected;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/periodictransactions/" + this.$store.state.periodicTransactions.id, this.$store.state, 'DELETE', null, false))) {
            this.name = "";
            this.cronExpression = "0 0 * * *";
            this.isActive = false;
            this.startDate = new Date().toISOString().split('T')[0];
            this.endDate = null;
            this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
            this.selectedAccount = this.getDefaultAccount(true);
            this.selectedSourceAccount = this.getDefaultAccount(false);
            this.selectedType = this.types[0];
            this.amount = 0.01;

            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    getMvvMPeriodicTransaction() {
      return GetMvvMPeriodicTransaction;
    },
    async getData() {
      this.$store.state.loading = true;

      await this.$store.state.dataset.setPage(this.$store, '/api/v1/periodictransactions/List', GetMvvMPeriodicTransaction);

      this.$store.state.loading = false;
    },
    async change() {
      this.$store.state.periodicTransactions.name = this.name.trim();

      let result = await CommunicationHelpers.apiDataCall("/api/v1/periodictransactions/IsDuplicate", this.$store.state, 'GET', { 'periodicTransactionName': this.$store.state.periodicTransactions.name }, false)

      if(result == "true" && this.name.trim() != this.oldName) {
        alert("Periodic transaction like that already exists. Choose different name");
        this.name = this.oldName;
      }
    },
    changeAmount() {
      let min = 0;
      let max = 9999999999999.99;

      if(this.amount < min || this.amount > max) {
        this.amount = this.oldAmount;
      } else {
        if(!this.amount) {
          this.amount = 0;
        }
        this.amount = this.amount.toFixed(2);
      }
    },
    getMinDate() {
      return addDays(this.startDate, 1);
    },
    changeDate() {
      let date = Date.parse(this.date);

      let min = new Date(1753, 1, 1);
      let max = new Date(9999, 12, 31);

      if(date < min || date > max) {
        this.date = this.oldDate;
      }
    },
    getDefaultAccount(findDefault) {
      let toReturn = null;
      let defaultAccount = this.accounts.find(account => account.isDefault);
      let nonDefaultAccount = this.accounts.find(account => !account.isDefault);

      if (findDefault && defaultAccount) {
        toReturn = defaultAccount;
      } else {
        toReturn = nonDefaultAccount;
      }

      return toReturn;
    },
    getAccounts() {
      return this.accounts.filter(account => {
        return account.id != this.selectedSourceAccount?.id;
      });
    },
    getDayFromCronExpression(cronExpression) {
      let dayId = cronExpression.split(' ')[2];
      let day = this.days.find(d => d.id.toString() === dayId);
      return day ? day.name : '';
    },
    getMonthFromCronExpression(cronExpression) {
      let monthId = cronExpression.split(' ')[3];
      let month = this.months.find(m => m.id.toString() === monthId);
      return month ? month.name : '';
    }
  },
  watch: {
    pageSize: async function() {
      this.$store.state.dataset.setPerPage(this.pageSize);

      await this.search();
    },
    startDate: function() {
      if(this.endDate && new Date(this.startDate) >= new Date(this.endDate)) {
        this.endDate = null;
      }
    },
    cronExpression: function() {
      this.day = this.days.find(d => d.id.toString() === this.cronExpression.split(' ')[2]) || this.days[0];
      this.month = this.months.find(m => m.id.toString() === this.cronExpression.split(' ')[3]) || this.months[0];
    },
    day: function() {
      this.cronExpression = `0 0 ${this.day.id} ${this.month.id} *`;
    },
    month: function() {
      this.cronExpression = `0 0 ${this.day.id} ${this.month.id} *`;
    }
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.from = 0;
    this.$store.state.take = 0;
    this.$store.state.searchString = "";
    next();
  }
};
</script>
