<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
                <div class="block-data block" style="min-height: 0px!important">
                    <h3>Welcome!</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        Here you can join us <b>for free</b> and we'll help you start managing your finances right away!
                    </div>
                </div>
            </div>
            <div id="registerControl" class="col-xs-12 col-sm-8 col-md-9">
                <div class="block block-scaf block-data">
                    <label for="Username">Username:</label>
                    <br />
                    <input id="Username" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="focus('RecoveryEmail')" v-model="username" />
                    <span class="tdspaced" style="color: red;" v-if="triedRegistering && !username.trim()">*</span>
                    <br />
                    <br />
                    <label for="RecoveryEmail">Email:</label>
                    <br />
                    <input id="RecoveryEmail" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="focus('Password')" v-model="email" />
                    <span class="tdspaced" style="color: red;" v-if="triedRegistering && !email.trim()">*</span>
                    <span style="color: red; display: block; padding-top: 20px" v-if="!validateEmail(email) && email.trim()">Invalid format</span>
                    <br v-if="validateEmail(email) || !email.trim()" />
                    <br />
                    <label for="Password">Password:</label>
                    <br />
                    <input type="password" id="Password" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="focus('RepeatedPassword')" v-model="password" />
                    <span class="tdspaced" style="color: red;" v-if="triedRegistering && !password.trim()">*</span>
                    <br />
                    <br />
                    <label for="RepeatedPassword">Repeat Password:</label>
                    <br />
                    <input type="password" id="RepeatedPassword" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="register($event)" v-model="repeatedPassword" />
                    <span class="tdspaced" style="color: red;" v-if="triedRegistering && !repeatedPassword.trim()">*</span>
                    <br />
                    <button id="RegisterButton" class="btn btn-primary profileBtn" Width="60%" @click="register($event)">Create User</button>
                    <button id="CancelButton" class="btn btn-danger profileBtn" Width="60%" @click="cancel()">Cancel</button>
                </div>
            </div>
            <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
                <div class="block" style="min-height: 0px!important">
                    <h3>Welcome!</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        Here you can join us <b>for free</b> and we'll help you start managing your finances right away!
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";
import UserIdentity from "../../../models/UserIdentity.js";

export default {
  name: "ReGister",
  data() {
    return {
        username: "",
        email: "",
        password: "",
        repeatedPassword: "",
        triedRegistering: false
    }
  },

  methods: {
      validateEmail(value) {
        return CommunicationHelpers.validateEmail(value);
      },
      focus(id) {
        document.getElementById(id).focus();
      },
      async register(event) {
        this.triedRegistering = true;

        if(!this.username.trim() || !this.email.trim() || !this.password.trim() || !this.repeatedPassword.trim()) {
            event.preventDefault();
        } else {
            if(this.password.trim() == this.repeatedPassword.trim()) {
                if(this.password.trim().length < 8) {
                    alert("Password must contain at least 8 symbols");
                    this.password = "";
                    this.repeatedPassword = "";
                } else {
                    this.$store.state.loading = true;

                    this.triedRegistering = false;

                    this.$store.state.userIdentity = new UserIdentity();
                    this.$store.state.userIdentity.user.username = this.username.trim();
                    this.$store.state.userIdentity.user.recoveryEmail = this.email.trim();
                    this.$store.state.userIdentity.user.password = CommunicationHelpers.encodeStringToUtf8(this.username.trim() + ":" + this.password.trim());
                    
                    this.$store.state.tokenModel = await CommunicationHelpers.apiDataCall("/api/v1/auth/register", this.$store.state, 'POST',
                    {
                        'username': this.$store.state.userIdentity.user.username,
                        'encodedPassword': this.$store.state.userIdentity.user.password,
                        'recoveryEmail': this.$store.state.userIdentity.user.recoveryEmail
                    }, true);
                    localStorage.setItem("tokenModel", JSON.stringify(this.$store.state.tokenModel));
                    localStorage.setItem("tokenSetTime", Date.now());

                    if (this.$store.state.tokenModel && !CommunicationHelpers.isEmpty(this.$store.state.tokenModel)) {
                        localStorage.login = this.username.trim();
                        localStorage.tokenModel = JSON.stringify(this.$store.state.tokenModel);

                        this.$router.push('/');
                    } else {
                        this.$store.state.tokenModel = null;
                    }

                    this.$store.state.loading = false;
                }
            }
            else {
                alert("Passwords do not match");
                this.repeatedPassword = "";
            }
        }
      },
      cancel() {
          if(confirm("Are you sure?")) {
            this.$router.push('/');
          }
      }
  }
};
</script>