<template>
  <div class="container">
    <div class="row">
      <div class="col-xs-12">
        <div class="block block-login" style="text-align:center; min-height:0px;">
          <div id="NoticeId">
            <h3>{{title}}</h3>
            <span v-if="!this.$store.state.versionError">{{message}}</span>
            
          </div>
          <br />
          <div v-if="this.$store.state.versionError">
            <a :href="$store.state.apkDownloadUrl" target="_blank">Click here to download the latest version of the app</a>
          </div>
          <button v-if="!this.$store.state.versionError" id="ContinueButton" class="btn btn-primary profileBtn" @click="openPage('/')">Try again</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";

export default {
  name: "NoTice",
  data() {
    return {
      title: null,
      message: null
    }
  },
  async mounted() {
    if(localStorage.getItem("isFatalError")) {
      // this.title = "ACCESS DENIED";
      // this.message = localStorage.getItem("errorMessage");

      localStorage.removeItem("isFatalError");
      localStorage.removeItem("errorMessage");

      await this.$store.commit('resetStore', this.$store.state);
    } else if(localStorage.getItem("isVersionError")) {
      this.$store.state.versionError = true;
      this.title = localStorage.getItem("errorMessage");

      let versionMatch = this.title.match(/(\d+)\.(\d+)\s*$/);
      let state = {
        languageCode: this.$store.state.languageCode,
        apiVersion: versionMatch ? `${versionMatch[1]}.${versionMatch[2]}.0.0` : null,
        apiUrl: this.$store.state.apiUrl
      }

      localStorage.removeItem("isVersionError");
      localStorage.removeItem("errorMessage");
      this.$store.state.apkDownloadUrl = await CommunicationHelpers.apiDataCall("/api/v1/content", state, 'GET', { 'placement': "ApkDownloadUrl" }, false);
    } else {
      this.title = "SERVER IS DOWN";
      localStorage.clear();
    }
  },
  methods: {
    openPage(name) {
        this.$router.push(name);
    }
  }
};
</script>