import { createApp } from "vue";
import { createStore } from "vuex";
import { router } from "./router/index.js";
import App from "./App.vue";
import UserIdentity from "./models/UserIdentity";
import Dataset from "./models/Dataset.js";
import MvvMCategory from "./models/MvvMCategory.js";
import MvvMAccount from "./models/MvvMAccount.js";
import MvvMTransaction from "./models/MvvMTransaction.js";
import MvvMPeriodicTransaction from "./models/MvvMPeriodicTransaction.js";
import { Capacitor } from '@capacitor/core';
import apiVersion from "../../HA.WebAPI/version.json";

const store = createStore({
  state: {
    apiUrl: process.env.VUE_APP_BACKEND_HOST,
    apiVersion: apiVersion.version,
    languageCode: "en",
    apkDownloadUrl: null,
    shortHomePageUpdate: null,
    loading: false,
    userIdentity: new UserIdentity(),
    dataset: new Dataset(),
    categories: new MvvMCategory(),
    accounts: new MvvMAccount(),
    transactions: new MvvMTransaction(),
    periodicTransactions: new MvvMPeriodicTransaction(),
    tokenModel: null,
    searchString: "",
    data: [],
    oldData: [],
    rowCount: 0,
    from: 0,
    take: 0,
    typeId: null,
    categoryIds: [],
    accountIds: [],
    dateTimeFrom: null,
    dateTimeTo: null,
    isWide: false,
    tokenLifeSpan: 900000,
    isWeb: Capacitor.getPlatform() == 'web'
  },
  mutations: {
    resetStore(state) {
    state.loading = true;
    state.userIdentity = new UserIdentity();
    state.tokenModel = null;
    state.searchString = "";

    localStorage.removeItem("tokenModel");
    localStorage.removeItem("login");
    localStorage.removeItem("tokenSetTime");

    clearInterval();

    if(location.pathname != "/") {
      location.hash = "/";
    }
    state.loading = false;
    }
  }
  });

const app = createApp(App);

app.use(store);
app.use(router);

app.mount('#darken');
