import CommunicationHelpers from '../helpers/CommunicationHelpers.js'

export default class Dataset {
  constructor() {
    this.flatData = [];
    this.items = [];
    
    this.perPage = 50;
    this.currentPage = 1;
    this.totalPages = 1;
  }

  setPerPage(value) {
    value = parseInt(value);

    if(value && value >= 5) {
      this.perPage = value;
    } else {
      this.perPage = 5;
    }
    
    return this.perPage;
  }

  async setPage(store, url, type) {
    store.state.from = (this.currentPage - 1) * this.perPage;
    store.state.take = ((this.totalPages * this.perPage) - store.state.from >= this.perPage ? this.perPage : (this.totalPages * this.perPage) - store.state.from);
    store.state.take = store.state.take > 0 ? store.state.take : this.perPage;
    
    let request = {
      from: store.state.from,
      take: store.state.take,
      dateTimeFrom: store.state.dateTimeFrom ?? '',
      dateTimeTo: store.state.dateTimeTo ?? '',
      typeId: store.state.typeId ?? '',
      categoryIds: JSON.stringify(store.state.categoryIds) ?? '[]',
      accountIds: JSON.stringify(store.state.accountIds) ?? '[]',
      searchString: store.state.searchString ?? ''
    };
    let response = await CommunicationHelpers.apiDataCall(url, store.state, 'GET', request, false);
    
    if(response) {
      store.state.rowCount = response.rowCount;
      store.state.oldData = response.rows;
      store.state.data = JSON.parse(JSON.stringify(store.state.oldData));

      this.items = await store.state.data.map(el => type(el, store, response));
    } else {
      store.state.rowCount = 0;
      store.state.oldData = [];
      store.state.data = [];

      this.items = [];
    }

    this.flatData = this.items;
    
    this.setTotalPages(store.state);
  }

  setData(data) {
    this.flatData = data;
  }

  setTotalPages(state) {
    this.totalPages = Math.ceil(state.rowCount / this.perPage);
  }

  async clear() {
    this.flatData = [];
    this.items = [];
  }
}