<template>
  <div class="container">
    <div class="row">
      <h2>Accounts</h2>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
        <div class="block-data block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your <b><i>accounts</i></b> that will be used for each data entry in <b><i>finance</i></b> tab. It is more efficient to manage your <b><i>finance</i></b> if you group them using <b><i>accounts</i></b>!
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-8 col-md-9">
        <div class="block block-data inner">
          <div class="inner">
            <div class="searchbar">
              <button id="NewButton" @click="insert()" data-toggle="modal" data-target="#detailModal" class="btn btn-primary up"><b>+</b> Add Account</button>
              <input id="Search" class="form-control search-box" maxlength="100" placeholder="Search" v-model="$store.state.searchString" @keyup="keyup" />
              <multiselect class="pageSize" id="PageFilter" v-model="pageSize" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="['10','15','20','25']" :preselectFirst="true" :allowEmpty="false"
                placeholder="Select" openDirection="bottom" >
              </multiselect>
            </div>
            <div class="table-place">
              <table class="table accounts">
                <thead>
                    <th class="accounts-nr">
                        Nr.
                    </th>
                    <th class="accounts-name">
                        Name
                    </th>
                    <th class="accounts-amount">
                        Balance
                    </th>
                    <th class="accounts-default">
                        Is Default
                    </th>
                </thead>
                <tbody>
                  <tr v-if="$store.state.dataset.items.length == 0">
                    <td colspan="5" class="no-data">No data available in table</td>
                  </tr>
                  <tr v-else v-for="(row, i) in $store.state.dataset.items" :key="row.id" @click="edit(row, i)" data-toggle="modal" data-target="#detailModal" :class="selected == row.id ? 'selected' : ''">
                    <td class="accounts-nr">
                      {{i + 1 + $store.state.from}}
                    </td>
                    <td class="accounts-name">
                      <div class="overflow-ellipsis">{{row.name}}</div>
                    </td>
                    <td class="accounts-amount">
                      {{row.amount >= 1000000 ? (row.amount/1000000).toFixed(0) + " M" : row.amount.toFixed(2) }}
                    </td>
                    <td class="accounts-default">
                      {{row.isDefault ? "Yes" : "No"}}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
            <Pagination :visibleButtonNumber="5" :baseUrl="'/api/v1/account/List'" :mvvMGetter="getMvvMAccount()" />
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
        <div class="block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your <b><i>accounts</i></b> that will be used for each data entry in <b><i>finance</i></b> tab. It is more efficient to manage your <b><i>finance</i></b> if you group them using <b><i>accounts</i></b>!
          </div>
        </div>
      </div>
    </div>
  </div>

  <div id="detailModal" class="modal fade" role="dialog" :v-model="this.selected">
    <div class="vertical-alignment-helper">
      <div class="modal-dialog vertical-align-center">
        <div class="modal-content">
          <div class="modal-header">
            <button type="button" class="close" data-dismiss="modal">&times;</button>
            <h4 class="modal-title">
            </h4>
          </div>
          <div class="modal-body">
            <label for="Name">Name</label>
            <br />
            <input id="Name" class="form-control form-text-valid" maxlength="100" @change="change($event)" v-on:keyup.enter="focus()" v-model="name" />
            <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !name.trim()">*</span>
            
            <div id="amountDisplay">
              <br />
              <label for="Amount">Balance</label>
              <br />
              <input id="Amount" class="form-control" disabled v-model="amount" />
            </div>

            <div v-if="this.selectedAccount && !this.selectedAccount.isDefault">
              <br />
              <button id="MakeDefault" @click="makeDefault($event)" class="btn btn-danger">Make default</button>
            </div>

          </div>
          <div class="modal-footer">
            <div id="newControl">
              <button id="AddButton" @click="addRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <div id="editControl">
              <button id="DeleteButton" @click="deleteRecord($event)" class="btn btn-danger leftside">Delete</button>
              <button id="SaveButton" @click="saveRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <button id="close" type="button" class="btn btn-default rightside" data-dismiss="modal" style="display:inline-block">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import jQuery from "jquery";
import Pagination from '../../Pagination/Pagination.vue';
import CommunicationHelpers from '../../../helpers/CommunicationHelpers.js';
import { GetMvvMAccount } from '../../../models/MvvMAccount.js';
import Dataset from '@/models/Dataset';
import Multiselect from 'vue-multiselect';
const $ = jQuery;
window.$ = $;

export default {
  name: "AccOunts",
  components: {
    Pagination,
    Multiselect
  },
  data() {
    return {
      pageSize: 10,
      selected: null,
      selectedAccount: null,
      name: "",
      amount: "0.00",
      oldName: "",
      triedSubmitting: false
    }
  },
  beforeMount() {
    this.$store.state.dataset = new Dataset();
  },
  async mounted() {
    this.$store.state.loading = true;

    await this.setup();

    this.$store.state.loading = false;
  },
  methods: {
    focus() {
      if(this.selected) {
        document.getElementById("SaveButton").click();
      } else {
        document.getElementById("AddButton").click();
      }
    },
    async setup() {
      this.$store.state.dataset.setPerPage(this.pageSize);
      await this.search();
    },
    async search() {
      this.$store.state.dataset.currentPage = 1;
      this.selected = null;
      this.selectedAccount = null;

      await this.getData();
    },
    async keyup() {
      // if (this.$store.state.loading) {
      //   event.preventDefault();
      // } else {
        await this.search();
      // }
    },
    insert() {
      this.selected = "";
      this.selectedAccount = null;
      this.oldName = "";
      this.name = "";

      document.getElementsByClassName("modal-title")[0].innerHTML = "Add new record";
      document.getElementById("newControl").style.display = "block";
      document.getElementById("editControl").style.display = "none";
      document.getElementById("amountDisplay").style.display = "none";
    },
    edit(row, i) {
      this.selected = row.id;
      this.selectedAccount = this.getSelectedAccount();

      this.name = row.name.trim();
      this.oldName = row.name.trim();
      this.amount = row.amount >= 1000000 ? (row.amount/1000000).toFixed(0) + " M" : row.amount.toFixed(2);

      document.getElementsByClassName("modal-title")[0].innerHTML = "Edit record nr. <b>" + (i + 1 + this.$store.state.from) + "</b>";
      document.getElementById("newControl").style.display = "none";
      document.getElementById("editControl").style.display = "block";
      document.getElementById("amountDisplay").style.display = "block";
    },
    getSelectedAccount() {
      return this.$store.state.dataset.items.find(account => account.id == this.selected);
    },
    async addRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim()) {
        event.preventDefault();
      } else {
        this.$store.state.loading = true;

        this.triedSubmitting = false;

        this.$store.state.accounts.id = 0;
        this.$store.state.accounts.name = this.name.trim();

        
        if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/account", this.$store.state, 'POST',
          { 'id': this.$store.state.accounts.id, 'name': this.$store.state.accounts.name, 'isDefault': false }, true))) {
          this.name = "";
          document.getElementById("close").click();

          await this.search();
        }

        this.$store.state.loading = false;
      }
    },
    async saveRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim()) {
          event.preventDefault();
      } else {
        this.triedSubmitting = false;

        if((this.name.trim() != this.oldName) && this.selected) {
          this.$store.state.loading = true;

          this.$store.state.accounts.id = this.selected;
          this.$store.state.accounts.name = this.name.trim();

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/account", this.$store.state, 'PUT',
            { 'id': this.$store.state.accounts.id, 'name': this.$store.state.accounts.name, 'isDefault': this.$store.state.accounts.isDefault }, true))) {
            this.name = "";
            document.getElementById("close").click();

            await this.search();
          }

          this.$store.state.loading = false;
        } else {
          document.getElementById("close").click();
        }
      }
    },
    async deleteRecord(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to delete?")) {
          this.$store.state.loading = true;

          this.$store.state.accounts.id = this.selected;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/account/" + this.$store.state.accounts.id, this.$store.state, 'DELETE', null, false))) {
            this.name = "";
            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    async makeDefault(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to make '" + this.selectedAccount.name + "' a default account?")) {
          this.$store.state.loading = true;

          this.$store.state.accounts.id = this.selected;
          this.$store.state.accounts.name = this.selectedAccount.name.trim();

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/account", this.$store.state, 'PUT',
            { 'id': this.$store.state.accounts.id, 'name': this.$store.state.accounts.name, 'isDefault': true }, true))) {
            this.name = "";
            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    getMvvMAccount() {
      return GetMvvMAccount;
    },
    async getData() {
      this.$store.state.loading = true;

      await this.$store.state.dataset.setPage(this.$store, '/api/v1/account/List', GetMvvMAccount);

      this.$store.state.loading = false;
    },
    async change() {
      this.$store.state.accounts.name = this.name.trim();

      let result = await CommunicationHelpers.apiDataCall("/api/v1/account/IsDuplicate", this.$store.state, 'GET', { 'accountName': this.$store.state.accounts.name }, false);

      if(result == "true" && this.name.trim() != this.oldName) {
        alert("Account like that already exists. Choose different name");
        this.name = this.oldName;
      }
    }
  },
  watch: {
    pageSize: async function() {
      this.$store.state.dataset.setPerPage(this.pageSize);

      await this.search();
    }
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.from = 0;
    this.$store.state.take = 0;
    this.$store.state.searchString = "";
    next();
  }
};
</script>
<style src="vue-multiselect/dist/vue-multiselect.min.css"></style>