import HARequest from "../models/HARequest.js";

export default class CommunicationHelpers {
    static async apiDataCall(url, state, method, request, hasBody) {
        let urlParameters = "";
        if(request != null && !hasBody) {
            let params = new URLSearchParams(request);

            const cleanParams = new URLSearchParams(
                Object.entries(Object.fromEntries(params)).filter(([, v]) => v != null && v !== '' && v !== 'null')
            );

            urlParameters = cleanParams.toString() ? `?${cleanParams.toString()}` : "";
        }

        return await this.apiPost(url + urlParameters, state, method,
            {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'version': state.apiVersion,
                'languageCode': state.languageCode,
                'Authorization': 'Bearer ' + state.tokenModel?.accessToken
            }, hasBody ? JSON.stringify(request) : null);
    }

    static async apiDataPost(url, state) {
        let request = this.createRequest(state);
        
        return await this.apiPost(url, state, 'POST', { 'Accept': 'application/json', 'Content-Type': 'application/json' }, JSON.stringify(request));
    }

    static async apiImport(url, data, state) {
        return await this.apiPost(url, state, 'POST', {
                'version': state.apiVersion,
                'languageCode': state.languageCode,
                'Authorization': 'Bearer ' + state.tokenModel?.accessToken
            }, data);
    }

    static async apiPost(url, state, method, headers, body) {
        let tokenSetTime = localStorage.getItem("tokenSetTime");

        if(tokenSetTime && (Date.now() - tokenSetTime > state.tokenLifeSpan) && location.pathname != "/") {
            localStorage.removeItem("tokenModel");
            localStorage.removeItem("login");

            location.hash = "/";
        }

        const response = await fetch(state.apiUrl + url, {
            method: method,
            headers: headers,
            body: body
        }).catch(() => {
            location.hash = "/notice";
        });
    
        var result = await response.json();
        
        if(result.message.errors.length > 0) {
            state.loading = false;
            state.completed = true;
            state.preventLoading = true;
        } else {
            state.preventLoading = false;
        }

        this.getAlerts(result);

        if(result.authenticationAnswer.isFatalError || localStorage.getItem("isFatalError")) {
            localStorage.setItem("isFatalError", result.authenticationAnswer.isFatalError);
            localStorage.setItem("errorMessage", result.authenticationAnswer.errorMessage +
                (result.processId ? " (" + result.processId + ")" : ""));

            localStorage.removeItem("tokenModel");
            localStorage.removeItem("login");

            location.hash = "/notice";
        }

        let versionError = result.message.errors.find(e => e.includes("Please update the app to support version"));
        if(versionError) {
            localStorage.setItem("isVersionError", true);
            localStorage.setItem("errorMessage", versionError);

            location.hash = "/notice";
        }
        
        return result.result;
    }

    static getAlerts(response) {
        var variant = [];
        var message = [];
    
        if(response.message != null) {
            if(response.message.infos != null){
                for(var i = 0; i < response.message.infos.length; i++) {
                    variant.push("info");
                    message.push(response.message.infos[i] + (response.processId ? " (" + response.processId + ")" : ""));
                }
            }
            if(response.message.warnings != null){
                for(i = 0; i < response.message.warnings.length; i++) {
                    variant.push("warning");
                    message.push(response.message.warnings[i] + (response.processId ? " (" + response.processId + ")" : ""));
                }
            }
            if(response.message.errors != null){
                for(i = 0; i < response.message.errors.length; i++) {
                    variant.push("danger");
                    message.push(response.message.errors[i] + (response.processId ? " (" + response.processId + ")" : ""));
                }
            }
            
            this.displayAlerts(variant, message);
        }
    }

    static async displaySuccessResponse(message) {
        let toReturn = false;
        
        if(message && !this.isEmpty(message)) {
            this.displayAlerts(["success"], [message]);

            let elements = document.getElementsByClassName("alert-success");

            while (elements.length > 0) {
                await new Promise(r => setTimeout(r, 7000));

                if(elements[0]) {
                    elements[0].remove();
                }
            }

            toReturn = true;
        }

        return toReturn;
    }
    
    static displayAlerts(variant, message) {
        if(variant && variant.length > 0) {
            scroll(0,0);
            for(var i = 0; i < variant.length; i++) {
                document.getElementById("alerts").innerHTML += "<div class='alert alert-" + variant[i] +
                    " alert-dismissible'><button type='button' class='close' data-dismiss='alert'>&times;</button><strong>" +
                    variant[i].toUpperCase() + "!</strong> " + message[i]  + "</div>";
            }
        }
    }

    static createRequest(state) {
        let request = new HARequest();

        request.userIdentity = state.userIdentity;
        request.apiVersion = state.apiVersion;
        request.languageCode = state.languageCode;
        request.tokenModel = state.tokenModel;
        request.searchString = state.searchString;
        request.name = state.name;
        request.email = state.email;
        request.message = state.message;
        request.from = state.from;
        request.take = state.take;
        request.names = state.names;
        request.accounts = state.accounts;
        request.finances = state.finances;
        request.periodicTransactions = state.periodicTransactions;
        request.typeId = state.typeId;
        request.categoryIds = state.categoryIds;
        request.accountIds = state.accountIds;
        request.dateTimeFrom = state.dateTimeFrom;
        request.dateTimeTo = state.dateTimeTo;

        return request;
    }

    static encodeStringToUtf8(value) {
        let utf8 = unescape(encodeURIComponent(value));

        let arr = [];
        for (let i = 0; i < utf8.length; i++) {
            arr.push(utf8.charCodeAt(i));
        }

        return btoa(String.fromCharCode.apply(null, new Uint8Array(arr)));
    }

    static validateEmail(value) {
        return value.toLowerCase().match(
          /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
        );
    }

    static isEmpty(obj) {
        return Object.keys(obj).length === 0;
    }
}