
export default class ContentHelpers {
    static getContentHtml(content) {
        const escAttr = (s) => String(s == null ? '' : s)
            .replace(/&/g, '&amp;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');

        const parts = [];

        if (content.title) {
            parts.push(`<h1>${escAttr(content.title)}</h1>`);
        }

        if (content.text) {
            // text is treated as HTML content (do not escape)
            parts.push(`<div class="content-text">${content.text}</div>`);
        }

        if (content.image && content.image.source) {
            const img = `<img src="${escAttr(content.image.source)}" alt="${escAttr(content.image.altText || '')}">`;
            if (content.image.link) {
                parts.push(`<div class="content-image"><a href="${escAttr(content.image.link)}" target="_blank" rel="noopener noreferrer">${img}</a></div>`);
            } else {
                parts.push(`<div class="content-image">${img}</div>`);
            }
        }

        if (content.button && content.button.text) {
            const href = content.button.link ? escAttr(content.button.link) : '#';
            parts.push(`<div class="content-button"><a class="btn" href="${href}" target="_blank" rel="noopener noreferrer">${escAttr(content.button.text)}</a></div>`);
        }

        content = parts.join('\n');
        return content;
    }
}