<template>
  <div class="container">
    <div class="row">
      <h2>Finance</h2>
      <div class="col-xs-12 col-sm-4 col-md-3" v-if="balance">
        <div class="block" style="min-height: 0px!important" v-if="balance">
          <div class="balance">
            <b>
              Total Balance:
              <div class="rightside">
                {{balance.totalBalance.toFixed(2)}}
              </div>
            </b>
          </div>
        </div>
        <div class="block block-data" style="min-height: 0px!important" >
          <div @click="toggleFilters()"><b>Filters</b><span style="float:right; color:grey">{{$store.state.isWide ? '' : (filtersEnabled ? 'hide' : 'show')}}</span></div>
          <div v-if="filtersEnabled || $store.state.isWide">
            <hr>
            <div class="filter">
              <div class="checkbox">
                <input type="checkbox" id="TypeCheckBox" value=this.typesFilter @change="typesFilter = !typesFilter" />
                <label for="TypeCheckBox">Type</label>
              </div>
              <multiselect v-if="typesFilter" id="TypesFilter" v-model="selectedTypeFilter" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="types" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                placeholder="Select" track-by="id" label="name" openDirection="bottom" >
              </multiselect>
              <div class="checkbox">
                <input type="checkbox" id="AccountCheckBox" @change="accountsFilter = !accountsFilter" />
                <label for="AccountCheckBox">Accounts</label>
              </div>
              <div v-if="accountsFilter">
                <multiselect id="AccountsFilter" v-model="selectedAccountFilter" :show-labels="false"
                  :closeOnSelect="false" :options="accounts" :multiple="true" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="name" openDirection="bottom" >
                  <template #noResult>
                    <span>No accounts found.</span>
                  </template>
                </multiselect>
              </div>
              <div class="checkbox">
                <input type="checkbox" id="NameCheckBox" @change="namesFilter = !namesFilter" />
                <label for="NameCheckBox">Categories</label>
              </div>
              <div v-if="namesFilter">
                <multiselect id="NamesFilter" v-model="selectedNameFilter" :show-labels="false"
                  :closeOnSelect="false" :options="names" :multiple="true" group-values="categories" group-label="name" :group-select="true"
                  placeholder="Select" track-by="id" label="name" openDirection="bottom" >
                  <template #noResult>
                    <span>No categories found.</span>
                  </template>
                </multiselect>
              </div>
              <div class="checkbox">
                <input type="checkbox" id="DateCheckBox" @change="datesFilter = !datesFilter" />
                <label for="DateCheckBox">Date</label>
              </div>
              <div v-if="datesFilter">
                <VueDatePicker v-model="calendarDate" range :preset-dates="presetDates" :enable-time-picker="false" :text-input="textInputOptions" :format="format" />
              </div>
              <hr>
              <div class="text">
                Income:
                <div class="rightside">
                  {{balance.income.toFixed(2)}}
                </div>
              </div>
              <div class="text">
                Expense:
                <div class="rightside">
                  {{balance.expense.toFixed(2)}}
                </div>
              </div>
              <div class="text">
                <b>
                  Balance:
                  <div class="rightside">
                  {{balance.balance.toFixed(2)}}
                </div>
                </b>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-8 col-md-9">
        <div class="block block-data inner">
          <div class="inner">
            <div class="searchbar">
              <button id="NewButton" @click="insert()" data-toggle="modal" data-target="#detailModal" class="btn btn-primary up"><b>+</b> Add Transaction</button>
              <input id="Search" class="form-control search-box financeForm" maxlength="100" placeholder="Search by Notes" v-model="$store.state.searchString" @keyup="keyup" />
              <multiselect class="pageSize" id="PageFilter" v-model="pageSize" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="['10','15','20','25']" :preselectFirst="true" :allowEmpty="false"
                placeholder="Select" openDirection="bottom" >
              </multiselect>
            </div>
            <div class="table-place">
              <table class="table finance">
                <thead>
                    <th class="finance-nr">
                        No
                    </th>
                    <th class="finance-account">
                        Account
                    </th>
                    <th class="finance-name">
                        Source
                    </th>
                    <th class="finance-amount">
                        Amount
                    </th>
                    <th class="finance-date">
                        Date
                    </th>
                    <th class="finance-comments">
                        Notes
                    </th>
                </thead>
                <tbody>
                  <tr v-if="$store.state.dataset.items.length == 0">
                    <td colspan="4" class="no-data">No data available in table</td>
                  </tr>
                  <tr v-else v-for="(row, i) in $store.state.dataset.items" :key="row.id" @click="edit(row, i)" data-toggle="modal" data-target="#detailModal" :class="(selected == row.id && row.type.factor == 1) ? 'selected-income' : (selected == row.id && row.type.factor == -1 ? 'selected-expense' : (row.type.factor == -1 ? 'expense' : (row.type.factor == 1 ? 'income' : '')))">
                    <td class="finance-nr">
                      {{i + 1 + $store.state.from}}
                    </td>
                    <td class="finance-account">
                      <div class="overflow-ellipsis">{{row.account?.name ?? ""}}</div>
                    </td>
                    <td class="finance-name">
                      <div class="overflow-ellipsis">{{getMvvMName(row.category)?.name ?? row.sourceAccount?.name ?? ""}}</div>
                    </td>
                    <td class="finance-amount">
                      {{row.amount >= 1000000 ? (row.amount/1000000).toFixed(0) + " M" : row.amount.toFixed(2) }}
                    </td>
                    <td class="finance-date">
                      {{row.date.split('T')[0]}}
                    </td>
                    <td class="finance-comments too_long">
                      <div class="overflow-ellipsis">{{row.comments}}</div>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
            <Pagination :visibleButtonNumber="5" :baseUrl="'/api/v1/transactions/List'" :mvvMGetter="getMvvMTransaction()" />
          </div>
        </div>
      </div>
    </div>
  </div>

  <div id="detailModal" class="modal fade" role="dialog">
    <div class="vertical-alignment-helper">
      <div class="modal-dialog vertical-align-center">
        <div class="modal-content">
          <div class="modal-header">
            <button type="button" class="close" data-dismiss="modal">&times;</button>
            <h4 class="modal-title">
            </h4>
          </div>
          <div class="modal-body">
            <label for="Types">Type</label>
            <br />
            <multiselect class="form-text-valid" id="Types" v-model="selectedType" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="types" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                placeholder="Select" track-by="id" label="name" openDirection="bottom" >
              </multiselect>
            <br />
            <br />
            <div v-if="selectedType?.name == 'Transfer'">
              <label for="Accounts">Source account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedSourceAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="accounts" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
              <label for="Accounts">Destination account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="getAccounts()" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
            </div>
            <div v-else>
              <label for="Accounts">Account</label>
              <br />
              <multiselect class="form-text-valid" id="Accounts" v-model="selectedAccount" :searchable="false" :show-labels="false"
                  :closeOnSelect="true" :options="accounts" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="account" openDirection="bottom" >
                </multiselect>
              <br />
              <br />
              <label for="Names">Category</label>
              <br />
              <multiselect class="form-text-valid" id="Names" v-model="selectedName" :show-labels="false"
                  :closeOnSelect="true" :options="names" group-values="categories" group-label="name" :preselectFirst="true" :allowEmpty="false" :customLabel="customNameLabel"
                  placeholder="Select" track-by="id" label="name" openDirection="bottom" >
                  <template #noResult>
                    <span>No categories found.</span>
                  </template>
                </multiselect>
              <br />
              <br />
            </div>
            <label for="Amount">Amount</label>
            <br />
            <input type="number" id="Amount" class="form-control form-text-valid" v-on:keyup.enter="focus()" @change="changeAmount()" v-model="amount" />
            <br />
            <br />
            <label for="Date">Date</label>
            <br />
            <VueDatePicker id="Date" v-model="date" :enable-time-picker="false" :text-input="textInputOptions" v-on:keyup.enter="focus()" :clearable="false" :format="formatSingle" />
            <br />
            <label for="Comments">Notes</label>
            <br />
            <input id="Comments" class="form-control form-text-valid" v-on:keyup.enter="focus()" v-model="comments" />
          </div>
          <div class="modal-footer">
            <div id="newControl">
              <button id="AddButton" @click="addRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <div id="editControl">
              <button id="DeleteButton" @click="deleteRecord($event)" class="btn btn-danger leftside">Delete</button>
              <button id="SaveButton" @click="saveRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <button id="close" type="button" class="btn btn-default rightside" data-dismiss="modal" style="display:inline-block">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import Pagination from '../../Pagination/Pagination.vue';
import CommunicationHelpers from '../../../helpers/CommunicationHelpers.js';
import MvvMTransaction, { GetMvvMTransaction } from '../../../models/MvvMTransaction.js';
import jQuery from "jquery";
import Dataset from '@/models/Dataset';
import Multiselect from 'vue-multiselect';
import VueDatePicker from '@vuepic/vue-datepicker';
import '@vuepic/vue-datepicker/dist/main.css';
import { endOfMonth, endOfYear, startOfMonth, startOfYear, subMonths, addDays, subYears } from 'date-fns';
const $ = jQuery;
window.$ = $;

export default {
  name: "FinAnce",
  components: {
    Pagination,
    Multiselect,
    VueDatePicker
  },
  data() {
    return {
      pageSize: 10,
      selected: null,
      balance: null,
      types: [],
      selectedType: null,
      names: [],
      accounts: [],
      selectedName: null,
      selectedAccount: null,
      selectedSourceAccount: null,
      amount: 0.01,
      date: new Date().toISOString().split('T')[0],
      comments: "",
      typesFilter: false,
      namesFilter: false,
      accountsFilter: false,
      datesFilter: false,
      selectedNameFilter: [],
      selectedAccountFilter: [],
      selectedTypeFilter: null,
      dateTimeFrom: null,
      dateTimeTo: null,
      filtersEnabled: false,
      width: 0,
      calendarDate: null,
      presetDates: [
        { label: 'Today', value: [new Date(), new Date()] },
        { label: 'This month', value: [startOfMonth(new Date()), endOfMonth(new Date())] },
        {
          label: 'Last month',
          value: [startOfMonth(subMonths(new Date(), 1)), endOfMonth(subMonths(new Date(), 1))],
        },
        {
          label: 'Last 3 months',
          value: [startOfMonth(subMonths(new Date(), 3)), endOfMonth(subMonths(new Date(), 1))],
        },
        { label: 'This year', value: [startOfYear(new Date()), endOfYear(new Date())] },
        { label: 'Last year', value: [startOfYear(subYears(new Date(), 1)), endOfYear(subYears(new Date(), 1))] }
      ],
      textInputOptions: {
        format: 'yyyy-MM-dd'
      }
    }
  },
  beforeMount() {
    if (this.$store.state.dataset.items.length > 0) {
      if(!this.$store.state.dataset.items[0].type) {
        this.$store.state.dataset = new Dataset();
      }
    }
  },
  async mounted() {
    this.$store.state.loading = true;

    if (innerWidth > 800) {
      this.$store.state.isWide = true;
    } else {
      this.$store.state.isWide = false;
    }

    window.addEventListener('resize', this.handleResize);

    await this.setup();

    this.$store.state.loading = false;
  },
  methods: {
    focus() {
      if(this.selected) {
        document.getElementById("SaveButton").click();
      } else {
        document.getElementById("AddButton").click();
      }
    },
    toggleFilters() {
      if (innerWidth > 800) {
        this.filtersEnabled = true;
      } else {
        this.filtersEnabled = !this.filtersEnabled;
      }

      this.reassureCheckBoxes();
    },
    handleResize() {
      if (innerWidth > 800) {
        this.$store.state.isWide = true;
      } else {
        this.$store.state.isWide = false;
      }

      this.reassureCheckBoxes();
    },
    async setup() {
      
      this.types = await CommunicationHelpers.apiDataCall("/api/v1/transactions/ListTypes", this.$store.state, 'GET', null, false);
      this.names = await CommunicationHelpers.apiDataCall("/api/v1/transactions/ListCategories", this.$store.state, 'GET', null, false);
      this.accounts = await CommunicationHelpers.apiDataCall("/api/v1/transactions/ListAccounts", this.$store.state, 'GET', null, false);

      if(this.names.length == 0) {
        this.$router.push('Categories');
      } else {
        this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
        this.selectedAccount = this.getDefaultAccount(true);
        this.selectedSourceAccount = this.getDefaultAccount(false);
        this.selectedType = this.types[0];

        this.selectedTypeFilter = this.types[0];
      }

      this.$store.state.dataset.setPerPage(this.pageSize);
      await this.search();
    },
    async search() {
      this.$store.state.loading = true;

      this.$store.state.dataset.currentPage = 1;
      this.selected = null;

      await this.getData();

      this.$store.state.loading = false;
    },
    async keyup() {
      // if (this.$store.state.loading) {
      //   event.preventDefault();
      // } else {
        await this.search();
      // }
    },
    format(date) {
      let toReturn = "";

      if (date[1]) {
        let offset = 1;

        if(date[1].toISOString().split('T')[0] == date[0].toISOString().split('T')[0]) {
          offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(date[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = date[1].toISOString().split('T')[0];
        toReturn = `${this.$store.state.dateTimeFrom}  -  ${this.$store.state.dateTimeTo}`;
      } else if(date[0]) {
        this.$store.state.dateTimeFrom = date[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
        toReturn = this.$store.state.dateTimeFrom;
      }

      return toReturn;
    },
    formatSingle(date) {
      return date.toISOString().split('T')[0];
    },
    reassureCheckBoxes() {
      if (this.filtersEnabled) {
        let type = document.getElementById("TypeCheckBox");
        if (this.typesFilter && type) {
          type.setAttribute("checked", "checked");
        }

        let name = document.getElementById("NameCheckBox");
        if (this.namesFilter && name) {
          name.setAttribute("checked", "checked");
        }

        let account = document.getElementById("AccountCheckBox");
        if (this.accountsFilter && account) {
          account.setAttribute("checked", "checked");
        }

        let date = document.getElementById("DateCheckBox");
        if (this.datesFilter && date) {
          date.setAttribute("checked", "checked");
        }
      }
    },
    customNameLabel({name, parentId, id}) {
      let toReturn = name;
      let found = this.names.find(item => item.id == parentId);

      if (found && id != found.id) {
        toReturn = found.name + " › " + toReturn;
      }

      this.reassureCheckBoxes();
      
      return toReturn;
    },
    insert() {
      this.selected = "";
      this.oldName = "";

      document.getElementsByClassName("modal-title")[0].innerHTML = "Add new record";
      document.getElementById("newControl").style.display = "block";
      document.getElementById("editControl").style.display = "none";
    },
    edit(row, i) {
      this.selected = row.id;

      let foundName = null;
      this.names.forEach(name => {
        if (name.id == row.category?.id) {
          foundName = name;
        } else {
          var subcategory = name.categories.find(item => item.id == row.category?.id);
          if (subcategory) {
            foundName = subcategory;
          }
        }
      });

      let foundAccount = null;
      this.accounts.forEach(account => {
        if (account.id == row.account?.id) {
          foundAccount = account;
        }
      });

      let foundSourceAccount = null;
      this.accounts.forEach(account => {
        if (account.id == row.sourceAccount?.id) {
          foundSourceAccount = account;
        }
      });

      this.selectedName = foundName;
      this.selectedAccount = foundAccount;
      this.selectedSourceAccount = foundSourceAccount;
      this.selectedType = row.type;
      this.amount = row.amount;
      this.date = row.date.split('T')[0];
      this.comments = row.comments.trim();

      this.oldName = foundName;
      this.oldAccount = foundAccount;
      this.oldSourceAccount = foundSourceAccount;
      this.oldType = row.type;
      this.oldAmount = row.amount;
      this.oldDate = row.date.split('T')[0];
      this.oldComments = row.comments.trim();

      document.getElementsByClassName("modal-title")[0].innerHTML = "Edit record nr. <b>" + (i + 1 + this.$store.state.from) + "</b>";
      document.getElementById("newControl").style.display = "none";
      document.getElementById("editControl").style.display = "block";
    },
    async addRecord() {
      this.$store.state.loading = true;

      this.changeDate();

      this.$store.state.transactions.name = this.selectedName;
      this.$store.state.transactions.account = this.selectedAccount;
      this.$store.state.transactions.sourceAccount = this.selectedSourceAccount;
      this.$store.state.transactions.type = this.selectedType;
      this.$store.state.transactions.amount = this.amount;
      this.$store.state.transactions.date = this.date;
      this.$store.state.transactions.comments = this.comments.trim();
      
      let request = {
        id: this.$store.state.transactions.id,
        category: this.$store.state.transactions.name,
        account: this.$store.state.transactions.account,
        sourceAccount: this.$store.state.transactions.sourceAccount,
        type: this.$store.state.transactions.type,
        amount: this.$store.state.transactions.amount,
        date: this.$store.state.transactions.date,
        comments: this.$store.state.transactions.comments
      };

      if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/transactions", this.$store.state, 'POST', request, true))) {
        this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
        this.selectedAccount = this.getDefaultAccount(true);
        this.selectedSourceAccount = this.getDefaultAccount(false);
        this.selectedType = this.types[0];
        this.amount = 0.01;
        this.date = new Date().toISOString().split('T')[0];
        this.comments = "";
        document.getElementById("close").click();

        await this.search();
      }
      
      this.$store.state.loading = false;
    },
    async saveRecord() {
      this.changeDate();

      if((this.selectedName != this.oldName ||
          this.selectedAccount != this.oldAccount ||
          this.selectedSourceAccount != this.oldSourceAccount ||
          this.selectedType != this.oldType ||
          this.amount != this.oldAmount ||
          this.date != this.oldDate ||
          this.comments.trim() != this.oldComments) && this.selected) {
        this.$store.state.loading = true;

        this.$store.state.transactions.id = this.selected;

        this.$store.state.transactions.name = this.selectedName;
        this.$store.state.transactions.account = this.selectedAccount;
        this.$store.state.transactions.sourceAccount = this.selectedSourceAccount;
        this.$store.state.transactions.type = this.selectedType;
        this.$store.state.transactions.amount = this.amount;
        this.$store.state.transactions.date = this.date;
        this.$store.state.transactions.comments = this.comments.trim();

        let request = {
          id: this.$store.state.transactions.id,
          category: this.$store.state.transactions.name,
          account: this.$store.state.transactions.account,
          sourceAccount: this.$store.state.transactions.sourceAccount,
          type: this.$store.state.transactions.type,
          amount: this.$store.state.transactions.amount,
          date: this.$store.state.transactions.date,
          comments: this.$store.state.transactions.comments
        };

        if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/transactions", this.$store.state, 'PUT', request, true))) {
          this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
          this.selectedAccount = this.getDefaultAccount(true);
          this.selectedSourceAccount = this.getDefaultAccount(false);
          this.selectedType = this.types[0];
          this.amount = 0.01;
          this.date = new Date().toISOString().split('T')[0];
          this.comments = "";
          document.getElementById("close").click();

          await this.search();
        }
        
        this.$store.state.loading = false;
      } else {
        document.getElementById("close").click();
      }
    },
    async deleteRecord(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to delete?")) {
          this.$store.state.loading = true;

          this.$store.state.transactions.id = this.selected;
        
          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/transactions/" + this.$store.state.transactions.id, this.$store.state, 'DELETE', null, false))) {
            this.selectedName = this.names[0]?.categories[0] ?? this.names[0];
            this.selectedAccount = this.getDefaultAccount(true);
            this.selectedSourceAccount = this.getDefaultAccount(false);
            this.selectedType = this.types[0];
            this.amount = 0.01;
            this.date = new Date().toISOString().split('T')[0];
            this.comments = "";

            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    getMvvMTransaction() {
      return GetMvvMTransaction;
    },
    getMvvMName(row) {
      let toReturn = row;

      if (row && row.categories && row.categories.length > 0) {
        toReturn.id = row.categories[0].id;
        toReturn.name = row.name + ' › ' + row.categories[0].name;
        toReturn.parentId = row.categories[0].parentId;
        toReturn.categories = [];
      }

      return toReturn;
    },
    async getData() {
      this.$store.state.transactions = new MvvMTransaction();
      let request = {
        from: this.$store.state.from,
        take: this.$store.state.take,
        dateTimeFrom: this.$store.state.dateTimeFrom ?? '',
        dateTimeTo: this.$store.state.dateTimeTo ?? '',
        typeId: this.$store.state.typeId ?? '',
        categoryIds: JSON.stringify(this.$store.state.categoryIds) ?? '[]',
        accountIds: JSON.stringify(this.$store.state.accountIds) ?? '[]',
        searchString: this.$store.state.searchString ?? ''
      };
      this.balance = await CommunicationHelpers.apiDataCall("/api/v1/transactions/Balance", this.$store.state, 'GET', request, false);

      await this.$store.state.dataset.setPage(this.$store, '/api/v1/transactions/List', GetMvvMTransaction);
    },
    changeAmount() {
      let min = 0;
      let max = 9999999999999.99;

      if(this.amount < min || this.amount > max) {
        this.amount = this.oldAmount;
      } else {
        if(!this.amount) {
          this.amount = 0;
        }
        this.amount = this.amount.toFixed(2);
      }
    },
    changeDate() {
      let date = Date.parse(this.date);

      let min = new Date(1753, 1, 1);
      let max = new Date(9999, 12, 31);

      if(date < min || date > max) {
        this.date = this.oldDate;
      }
    },
    getDefaultAccount(findDefault) {
      let toReturn = null;
      let defaultAccount = this.accounts.find(account => account.isDefault);
      let nonDefaultAccount = this.accounts.find(account => !account.isDefault);

      if (findDefault && defaultAccount) {
        toReturn = defaultAccount;
      } else {
        toReturn = nonDefaultAccount;
      }

      return toReturn;
    },
    getAccounts() {
      return this.accounts.filter(account => {
        return account.id != this.selectedSourceAccount?.id;
      });
    }
  },
  watch: {
    pageSize: async function() {
      this.$store.state.dataset.setPerPage(this.pageSize);

      await this.search();
    },
    typesFilter: async function() {
      this.$store.state.typeId = this.typesFilter ? this.selectedTypeFilter.id: null;

      await this.search();
    },
    namesFilter: async function() {
      this.$store.state.categoryIds = this.namesFilter ? this.selectedNameFilter.map(function(i) { return i.id }) : [];

      await this.search();
    },
    accountsFilter: async function() {
      this.$store.state.accountIds = this.accountsFilter ? this.selectedAccountFilter.map(function(i) { return i.id }) : [];

      await this.search();
    },
    datesFilter: async function() {
      this.$store.state.dateTimeFrom = this.datesFilter ? this.$store.state.dateTimeFrom : null;
      this.$store.state.dateTimeTo = this.datesFilter ? this.$store.state.dateTimeTo : null;

      await this.search();
    },
    selectedTypeFilter: async function() {
      this.$store.state.typeId = this.typesFilter ? this.selectedTypeFilter.id : null;

      await this.search();
    },
    selectedType: async function() {
      let row = null;

      this.$store.state.dataset.items.forEach(item => {
          if (item.id == this.selected) {
            row = item;
          }
        });

      let foundName = null;
      let foundAccount = null;
      let foundSourceAccount = null;

      if (row) {
        this.names.forEach(name => {
          if (row.category && name.id == row.category.id) {
            foundName = name;
          } else {
            var subcategory = name.categories.find(item => row.category && item.id == row.category.id);
            if (subcategory) {
              foundName = subcategory;
            }
          }
        });

        this.accounts.forEach(account => {
          if (row.account && account.id == row.account.id) {
            foundAccount = account;
          }
        });

        this.accounts.forEach(account => {
          if (row.sourceAccount && account.id == row.sourceAccount.id) {
            foundSourceAccount = account;
          }
        });
      }
      
      this.selectedName = foundName ?? this.names[0]?.names[0] ?? this.names[0];
      this.selectedAccount = foundAccount ?? this.getDefaultAccount(true);
      this.selectedSourceAccount = foundSourceAccount ?? this.getDefaultAccount(false);
      
      if (this.selectedAccount == this.getDefaultAccount(false)) {
        this.selectedAccount = this.getDefaultAccount(true);
      }

      if (this.selectedSourceAccount == this.getDefaultAccount(true)) {
        this.selectedSourceAccount = this.getDefaultAccount(false);
      }
    },
    selectedNameFilter: async function() {
      this.$store.state.categoryIds = this.namesFilter ? this.selectedNameFilter.map(function(i) { return i.id }) : [];

      await this.search();
    },
    selectedAccountFilter: async function() {
      this.$store.state.accountIds = this.accountsFilter ? this.selectedAccountFilter.map(function(i) { return i.id }) : [];

      await this.search();
    },
    selectedSourceAccountFilter: async function() {
      this.$store.state.accountIds = this.accountsFilter ? this.selectedSourceAccountFilter.map(function(i) { return i.id }) : [];

      await this.search();
    },
    calendarDate: async function() {
      if (this.calendarDate && this.calendarDate[1]) {
        let offset = 1;

        if(this.calendarDate[1].toISOString().split('T')[0] == this.calendarDate[0].toISOString().split('T')[0]) {
          offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(this.calendarDate[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.calendarDate[1].toISOString().split('T')[0];
      } else if(this.calendarDate && this.calendarDate[0]) {
        this.$store.state.dateTimeFrom = this.calendarDate[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
      } else {
        this.$store.state.dateTimeFrom = null;
        this.$store.state.dateTimeTo = null;
      }

      await this.search();
    },
    selectedSourceAccount() {
      if(this.selectedSourceAccount && this.selectedAccount && this.selectedSourceAccount.id == this.selectedAccount.id) {
        this.selectedAccount = this.getAccounts().length > 0 ? this.getAccounts()[0] : null;
      }
    }
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.dateTimeFrom = null;
    this.$store.state.dateTimeTo = null;
    this.$store.state.from = 0;
    this.$store.state.take = 0;
    this.$store.state.typeId = null;
    this.$store.state.accountIds = [];
    this.$store.state.categoryIds = [];
    this.$store.state.searchString = "";

    next();
  }
};
</script>
