<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
                <div class="block-data block" style="min-height: 0px!important">
                    <h3>Hmm...</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        <ul style="padding-left: 20px;">
                            <li>Having problems logging in?</li>
                            <li>Noticed bugs?</li>
                            <li>Have suggestions for future updates?</li>
                        </ul>Here you can contact the owner of <b>Accounting</b> website!
                    </div>
                </div>
            </div>
            <div class="col-xs-12 col-sm-8 col-md-9">
                <div class="block block-scaf">
                    <label for="name">Name:</label>
                    <br />
                    <input id="Name" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="focus('Email')" v-model="name" />
                    <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !name.trim()">*</span>
                    <br />
                    <br />
                    <label for="Email">Email:</label>
                    <br />
                    <input id="Email" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="focus('Message')" v-model="email" />
                    <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !email.trim()">*</span>
                    <span style="color: red; display: block; padding-top: 20px" v-if="!validateEmail(email) && email.trim()">Invalid format</span>
                    <br v-if="validateEmail(email) || !email.trim()" />
                    <br />
                    <label for="Message">Message:</label>
                    <br />
                    <textarea id="Message" class="form-control form-text-valid" style="resize:none; height:100px" v-model="message" />
                    <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !message.trim()">*</span>
                    <br />
                    <br />
                    <VueClientRecaptcha
                        :value="captcha"
                        :show-lower-case-letters="false"
                        :show-numbers="true"
                        :count="6"
                        @getCode="getCaptchaCode"
                        @isValid="checkValidCaptcha"
                    />
                    <input id="Captcha" class="form-control form-text-valid" maxlength="6" style="text-transform:uppercase" v-on:keyup.enter="submit($event)" v-model="captcha" />
                    <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !captcha.trim()">*</span>
                    <br />
                    <button id="SubmitButton" class="btn btn-primary profileBtn" Width="60%" @click="submit($event)">Submit</button>
                    <button id="CancelButton" class="btn btn-danger profileBtn" Width="60%" @click="cancel()">Cancel</button>
                </div>
                <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
                    <div class="block" style="min-height: 0px!important">
                        <h3>Hmm...</h3>
                        <hr>
                        <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                            <ul style="padding-left: 20px;">
                                <li>Having problems logging in?</li>
                                <li>Noticed bugs?</li>
                                <li>Have suggestions for future updates?</li>
                            </ul>
                            Here you can contact the owner of <b>Accounting</b> website!
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { ref } from "vue";
import VueClientRecaptcha from "vue-client-recaptcha";
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";

export default {
  name: "ContactUs",
  components: {
    VueClientRecaptcha
  },
  data() {
    return {
        name: "",
        email: "",
        message: "",
        captcha: ref(""),
        isValid: false,
        triedSubmitting: false
    }
  },

  methods: {
      validateEmail(value) {
        return CommunicationHelpers.validateEmail(value);
      },
      focus(id) {
        document.getElementById(id).focus();
      },
      getCaptchaCode() {
      },
      checkValidCaptcha(value) {
        this.isValid = value;
      },
      async submit(event) {
        this.triedSubmitting = true;
        
        if(!this.name.trim() || !this.email.trim() || !this.message.trim()) {
            event.preventDefault();
        } else {
            if(this.isValid) {
                this.$store.state.loading = true;

                this.triedSubmitting = false;

                this.$store.state.name = this.name.trim();
                this.$store.state.email = this.email.trim();
                this.$store.state.message = this.message.trim();
                
                if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/contactus", this.$store.state, 'POST',
                    { 'username': this.$store.state.name, 'emailAddress': this.$store.state.email, 'message': this.$store.state.message }, false))) {
                    this.name = "";
                    this.email = "";
                    this.message = "";
                    this.captcha = ref("");
                }
                
                this.$store.state.loading = false;
            } else {
                alert("Wrong Captcha");
            }
        }
      },
      cancel() {
          if(confirm("Are you sure?")) {
            this.$router.push('/');
          }
      }
  },
  watch: {
      captcha() {
          this.captcha = this.captcha.toUpperCase();
      }
  }
};
</script>